import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { ICmsLoanRegisterConfigRepository } from '@src/domain/interfaces/cms/loan_register/loanRegisterConfig';

export class GetCmsLoanRegisterConfigHandler {
    private readonly _cmsLoanRegisterConfigRepository: ICmsLoanRegisterConfigRepository;

    constructor(
        @inject(TYPES.ICmsLoanRegisterConfigRepository) CmsLoanRegisterConfigRepository: ICmsLoanRegisterConfigRepository,
    ) {
        this._cmsLoanRegisterConfigRepository = CmsLoanRegisterConfigRepository;
    }

    handle(segment: string) {
        return this._cmsLoanRegisterConfigRepository.getCmsLoanRegisterConfig(segment)
    }
}
